"""Contact matching benchmark: the workflow as a program. Generated by Agent Workflow Studio from the published
release; export again rather than edit (the steps it calls are in core/, unchanged from the studio)."""

from pathlib import Path

from .core import bench, runner, steps  # noqa: F401

HERE = Path(__file__).parent
TITLE, VERSION = 'Contact matching benchmark', '1.0.0'
PURPOSE = ('Measure contact matching on generated contacts with an answer key: the same stages as Contact '
 'matching, with a reviewer who knows the answers.')
# The workflow's App inputs: name -> [default, type, description, choices].
INPUTS = {'profile': ['company_hard',
             'COMBO',
             'How dirty, and with real names and companies or not (real and company profiles need '
             'the public sources downloaded once).',
             ['base',
              'dirty',
              'sparse',
              'lookalike',
              'wild',
              'hard',
              'real',
              'company',
              'company_hard',
              'real_hard']],
 'contacts': [10000, 'INT', 'About how many contacts to generate.', None],
 'seed': [7, 'INT', 'The same seed gives the same data.', None],
 'budget': [1000,
            'INT',
            'How many reviews the simulated reviewer makes (about 1,000 for a good model).',
            None]}
OUTPUTS = ['entities']
FOLDERS = []  # inputs that name a data folder
EXAMPLES = [{'id': 'E1',
  'given': {'profile': 'hard', 'contacts': 600, 'seed': 5, 'budget': 200},
  'expect': {'entities': 'record'},
  'note': 'A small hard set (no downloads needed): every contact gets an entity id and the score '
          'is shown.'}]


def run(out, labels=None, **given):
    """Run the workflow; `given` overrides any input. Returns the runtime (checks, outputs, lines)."""
    values = {k: (given[k] if given.get(k) is not None else d) for k, (d, *_) in INPUTS.items()}
    input_dir = Path(out)
    for name in FOLDERS:
        folder = Path(str(values[name]).replace("@examples", str(HERE / "examples"), 1)).resolve()
        if not folder.is_dir():
            raise SystemExit(f"No folder {folder} for --{name.replace('_', '-')}.")
        input_dir, values[name] = folder.parent, folder.name
    rt = runner.Runtime(Path(out), input_dir, labels)
    n12_1 = bench.synthetic_contacts(rt.ctx('synthetic_contacts'), profile=values['profile'], contacts=values['contacts'], seed=values['seed'])  # Synthetic contacts
    n12_13 = runner.check(rt.ctx('check'), kind='contains', expect='contacts_benchmark', says='The data folder is written (with its answer key beside it).', value=n12_1[0])  # Check · folder
    n14_2 = steps.read_contacts(rt.ctx('read_contacts'), folder=n12_1[0], columns='# Which column holds what. Files are in the data folder. Only key, birth_date and one name\n# column are required; leave out what your data does not have.\nkey: CONT_ID                      # or a list of columns that together identify a contact\ncontacts: contacts.csv\nsurname: {kanji: LAST_NAME_KANJI, kana: LAST_NAME_KANA, romaji: LAST_NAME_ROMAJI}\ngiven: {kanji: FIRST_NAME_KANJI, kana: FIRST_NAME_KANA, romaji: FIRST_NAME_ROMAJI}\nbirth_date: BIRTH_DATE            # or {column: 生年月日, format: "%Y/%m/%d"}\ngender: GENDER\ntype: {column: CONT_TYPE, company: ["2"]}   # the values that mean a company\nphones: {file: phones.csv, columns: [PHONE]}          # no file: columns of the contacts file\naddresses: {file: addresses.csv, kanji: [ADDRESS_KANJI]}  # several columns: parts of one address\n')  # Read contacts
    n14_15 = runner.check(rt.ctx('check'), kind='rows_at_least', expect='1', says='The exports are read: at least one contact (10,540 on the benchmark data).', value=n14_2[0])  # Check · contacts
    n16_3 = steps.standardize_contacts(rt.ctx('standardize_contacts'), towns=str(HERE / "reference" / 'towns.tsv'), kana_ocr=True, readings=True, split_one_field=True, shop_alias=True, company_clean=True, contacts=n14_2[0])  # Standardize contacts
    n16_17 = runner.check(rt.ctx('check'), kind='rows_at_least', expect='1', says='Every contact read is standardized.', value=n16_3[0])  # Check · records
    n18_4 = steps.find_contact_candidates(rt.ctx('find_contact_candidates'), exact=True, shared=True, locality=True, similar=True, exact_cap=50, shared_cap=20, similarity=0.5, records=n16_3[0])  # Find contact candidates
    n18_19 = runner.check(rt.ctx('check'), kind='rows_at_least', expect='1', says='Candidate pairs are found (15,219 on the benchmark data).', value=n18_4[0])  # Check · candidates
    n20_5 = steps.compare_contacts(rt.ctx('compare_contacts'), records=n16_3[0], candidates=n18_4[0])  # Compare contacts
    n20_21 = runner.check(rt.ctx('check'), kind='rows_at_least', expect='1', says='Every candidate pair is compared.', value=n20_5[0])  # Check · pairs
    n22_6 = steps.learn_from_reviews(rt.ctx('learn_from_reviews'), batch=50, audit=True, answer_key_file=n12_1[1], budget=values['budget'], seed=0, pairs=n20_5[0])  # Learn from your reviews
    n22_23 = runner.check(rt.ctx('check'), kind='rows_at_least', expect='1', says='Every compared pair gets a score.', value=n22_6[0])  # Check · scored
    n24_7 = steps.decide_pairs(rt.ctx('decide_pairs'), match_at=0.5, review_from=0.1, corroboration=False, pairs=n22_6[0])  # Decide by score
    n24_25 = runner.check(rt.ctx('check'), kind='rows_at_least', expect='1', says='Every scored pair is decided.', value=n24_7[0])  # Check · decisions
    n26_8 = steps.cluster_guard(rt.ctx('cluster_guard'), max_size=12, scores_separate=True, data=n24_7[0])  # Group into entities (guarded)
    n26_27 = runner.check(rt.ctx('check'), kind='rows_at_least', expect='1', says='The decided pairs are grouped.', value=n26_8[0])  # Check · clusters
    n28_9 = steps.entity_per_contact(rt.ctx('entity_per_contact'), records=n14_2[0], clusters=n26_8[0])  # Entity per contact
    n10 = runner.api_output(rt.ctx('api_output'), name='entities', value=n28_9[0])  # Output · entities
    n28_29 = runner.check(rt.ctx('check'), kind='rows_at_least', expect='1', says='Every contact gets an entity id.', value=n28_9[0])  # Check · entities
    n30_11 = bench.score_contacts(rt.ctx('score_contacts'), answer_key=n12_1[1], entities=n28_9[0])  # Score contacts
    return rt
